import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"asc_lock","link":"/api/SIMD-API/c_api/sync/asc_lock"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/asc_lock.md","filePath":"api/SIMD-API/c_api/sync/asc_lock.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"},{"level":3,"title":"多重循环场景：双buffer流水线优化","slug":"多重循环场景：双buffer流水线优化","link":"#多重循环场景：双buffer流水线优化"},{"level":4,"title":"优化前：单mutex_id串行（所有tile共用一个mutex_id）","slug":"优化前：单mutex_id串行（所有tile共用一个mutex_id）","link":"#优化前：单mutex_id串行（所有tile共用一个mutex_id）"},{"level":4,"title":"优化后：双mutex_id交替 + 双buffer","slug":"优化后：双mutex_id交替-+-双buffer","link":"#优化后：双mutex_id交替-+-双buffer"}],"lastUpdated":1788435672000}'),l={name:"api/SIMD-API/c_api/sync/asc_lock.md"};function _(t,s,i,e,w,d){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>asc_lock</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/sync/sync.h&quot;</code>。</p><p>该接口用于AI Core内部异步流水线之间的同步，可按需阻塞指定流水线的执行。</p><p>根据mutex_id获取Mutex，若Mutex已被锁定，将阻塞后续指定流水指令队列，直到当前流水的前序指令中对应mutex_id的Mutex被asc_unlock释放。</p><p>相对于<a href="asc_sync_notify.html">asc_sync_notify</a>/<a href="asc_sync_wait.html">asc_sync_wait</a>同步机制，使用asc_lock/asc_unlock接口有以下优势：</p><ul><li><p>内聚性更强，使用时与其它流水线解耦，可以简化反向同步。以PIPE_MTE2与PIPE_V之间同步为例，对比如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// asc_sync_notify/asc_sync_wait机制</span>
<span class="n">For</span><span class="w"> </span><span class="n">i</span><span class="o">=</span><span class="mi">0</span><span class="o">:</span><span class="mi">100</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="mi">0</span><span class="o">:</span>
<span class="w">        </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">    </span><span class="n">endif</span>
<span class="w">    </span><span class="c1">// MTE2指令</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">    </span><span class="c1">// PIPE_V指令</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">99</span><span class="o">:</span>
<span class="w">        </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">)</span>
<span class="w">    </span><span class="n">endif</span>
<span class="n">endFor</span>

<span class="c1">// asc_lock/asc_unlock机制</span>
<span class="n">For</span><span class="w"> </span><span class="n">i</span><span class="o">=</span><span class="mi">0</span><span class="o">:</span><span class="mi">100</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="w">    </span><span class="c1">// MTE2指令</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="w">    </span><span class="c1">// PIPE_V指令</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
<span class="n">endFor</span>
</code></pre></div><p>其中EVENT_ID0为同步ID，取值范围为[0, 7]；mutex_id取值范围为[0, 31]。</p></li><li><p>可以使用更多的同步信号量。</p></li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="nc">ascMutexExecuteMode</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ASC_LOCK_BLOCK</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">ASC_LOCK_NON_BLOCK</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span>
<span class="p">};</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">ascMutexExecuteMode</span><span class="w"> </span><span class="n">mode</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">pipe</td><td align="left">输入</td><td align="left">指定当前接口所属的流水类型。</td></tr><tr><td align="left">mutex_id</td><td align="left">输入</td><td align="left">mutex标号，取值范围为[0, 31]。</td></tr><tr><td align="left">mode</td><td align="left">输入</td><td align="left">可选参数，用于指定是否阻塞流水线，默认值为ASC_LOCK_BLOCK。<br>• ASC_LOCK_BLOCK：阻塞pipe对应流水线的执行，直到代码中位于当前asc_lock之前且mutex_id相同的所有asc_unlock调用均已执行完成。<br>• ASC_LOCK_NON_BLOCK：不阻塞pipe对应流水线的执行。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>asc_lock与asc_unlock必须严格成对使用，并使用相同的mutex_id与mode。此外，对应的asc_unlock必须始终写在asc_lock之后，否则硬件行为无定义。</li><li>对于mutex_id相同的asc_lock与asc_unlock组合，无论pipe和mode是否相同，都不得在代码中嵌套使用，否则硬件行为将不可预测。</li><li>成对使用的asc_lock和asc_unlock必须配置相同的mode，否则硬件行为将不可预测。</li><li>如果代码中连续出现多个pipe和mutex_id均相同的调用，则后一个asc_lock不会再阻塞流水线运行。若需要表达同一流水线内的依赖关系，必须使用接口asc_sync_pipe。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src0_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src1_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst_addr</span><span class="p">,</span>
<span class="w">                               </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_time</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_time</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b16</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign_postupdate</span><span class="p">(</span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src0_addr</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign_postupdate</span><span class="p">(</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">src1_addr</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_add</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign_postupdate</span><span class="p">(</span><span class="n">dst_addr</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">x_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">y_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">z_gm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">x_local</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">y_local</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">z_local</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// 1. PIPE_MTE2流水线：数据从GM搬入Unified Buffer（UB）</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">x_gm</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_gm</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="c1">// 数据搬入完成后释放mutex_id，使后续相同mutex_id的asc_lock不再阻塞</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 2. PIPE_V流水线：矢量计算</span>
<span class="w">    </span><span class="c1">// BLOCK模式下（默认），asc_lock阻塞PIPE_V执行，直到前序所有相同mutex_id的asc_unlock执行完成</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="w">    </span><span class="n">add_vf</span><span class="p">(</span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 计算完成后释放mutex_id，使后续PIPE_MTE3的asc_lock不再阻塞</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 3. PIPE_MTE3流水线：数据从UB搬出至GM</span>
<span class="w">    </span><span class="c1">// asc_lock阻塞PIPE_MTE3执行，直到PIPE_V的asc_unlock执行完成</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">z_gm</span><span class="p">,</span><span class="w"> </span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>上述示例的流水线时序如下，三条流水线严格串行执行：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>MTE2: |==搬入==|
V:              |==计算==|
MTE3:                   |==搬出==|
</code></pre></div><h3 id="多重循环场景：双buffer流水线优化">多重循环场景：双buffer流水线优化<a class="header-anchor" href="#多重循环场景：双buffer流水线优化">​</a></h3><p>当多轮循环中需要相邻轮次的MTE2（搬入）与MTE3（搬出）并行执行时，可使用<strong>两个mutex_id交替</strong>配合<strong>双buffer</strong>，实现软件流水线。同一mutex_id仅在间隔一轮（buffer复用）时才产生等待，从而重叠相邻轮次的搬运与计算。</p><h4 id="优化前：单mutex_id串行（所有tile共用一个mutex_id）">优化前：单mutex_id串行（所有tile共用一个mutex_id）<a class="header-anchor" href="#优化前：单mutex_id串行（所有tile共用一个mutex_id）">​</a></h4><p>所有tile使用相同mutex_id，下一轮的<code>asc_lock(PIPE_MTE2)</code>必须等待上一轮<code>asc_unlock(PIPE_MTE3)</code>完成，三阶段严格串行。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src0_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src1_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst_addr</span><span class="p">,</span>
<span class="w">                               </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_time</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_time</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b16</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign_postupdate</span><span class="p">(</span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src0_addr</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign_postupdate</span><span class="p">(</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">src1_addr</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_add</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign_postupdate</span><span class="p">(</span><span class="n">dst_addr</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_kernel_serial</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">x_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">y_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">z_gm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">x_local</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">y_local</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">z_local</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>

<span class="w">        </span><span class="c1">// 下一轮MTE2必须等待上一轮MTE3完成（相同mutex_id）</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">x_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="c1">// 释放mutex_id，使本轮PIPE_V的asc_lock不再阻塞</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="w">        </span><span class="n">add_vf</span><span class="p">(</span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// 释放mutex_id，使本轮PIPE_MTE3的asc_lock不再阻塞</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">z_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="c1">// 释放mutex_id，使下一轮PIPE_MTE2的asc_lock不再阻塞</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>优化前的流水线时序，各轮次之间严格串行：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>MTE2: |==id0==|                |==id0==|                |==id0==|                |==id0==|
V:          |==id0==|                |==id0==|                |==id0==|                |==id0==|
MTE3:            |==id0==|                |==id0==|                |==id0==|                |==id0==|
</code></pre></div><h4 id="优化后：双mutex_id交替-+-双buffer">优化后：双mutex_id交替 + 双buffer<a class="header-anchor" href="#优化后：双mutex_id交替-+-双buffer">​</a></h4><p>使用两个mutex_id交替配合双buffer，相邻轮次的MTE2与MTE3可并行执行。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_kernel_pingpong</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">x_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">y_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">z_gm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 双buffer：buf0和buf1交替使用</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">x_buf</span><span class="p">[</span><span class="mi">2</span><span class="p">][</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">y_buf</span><span class="p">[</span><span class="mi">2</span><span class="p">][</span><span class="mi">256</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">z_buf</span><span class="p">[</span><span class="mi">2</span><span class="p">][</span><span class="mi">256</span><span class="p">];</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 交替使用mutex_id 0和1</span>
<span class="w">        </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>

<span class="w">        </span><span class="c1">// 1. PIPE_MTE2流水线：数据从GM搬入UB buf[mutex_id]</span>
<span class="w">        </span><span class="c1">// 当i&gt;=2时，asc_lock阻塞，等待i-2轮的PIPE_MTE3 asc_unlock完成（buffer复用约束）</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">x_buf</span><span class="p">[</span><span class="n">mutex_id</span><span class="p">],</span><span class="w"> </span><span class="n">x_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">y_buf</span><span class="p">[</span><span class="n">mutex_id</span><span class="p">],</span><span class="w"> </span><span class="n">y_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="c1">// 释放mutex_id，使本轮PIPE_V的asc_lock不再阻塞</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">        </span><span class="c1">// 2. PIPE_V流水线：矢量计算</span>
<span class="w">        </span><span class="c1">// asc_lock阻塞，等待本轮PIPE_MTE2的asc_unlock完成</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="w">        </span><span class="n">add_vf</span><span class="p">(</span><span class="n">x_buf</span><span class="p">[</span><span class="n">mutex_id</span><span class="p">],</span><span class="w"> </span><span class="n">y_buf</span><span class="p">[</span><span class="n">mutex_id</span><span class="p">],</span><span class="w"> </span><span class="n">z_buf</span><span class="p">[</span><span class="n">mutex_id</span><span class="p">],</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// 释放mutex_id，使本轮PIPE_MTE3的asc_lock不再阻塞</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">        </span><span class="c1">// 3. PIPE_MTE3流水线：数据从UB搬出至GM</span>
<span class="w">        </span><span class="c1">// asc_lock阻塞，等待本轮PIPE_V的asc_unlock完成</span>
<span class="w">        </span><span class="c1">// 本轮MTE3可与下一轮（mutex_id不同）的MTE2并行执行</span>
<span class="w">        </span><span class="c1">// 释放mutex_id后，下一轮使用不同mutex_id的asc_lock不会阻塞</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">z_gm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">z_buf</span><span class="p">[</span><span class="n">mutex_id</span><span class="p">],</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>优化后的流水线时序，相邻轮次的MTE2与MTE3并行执行：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>MTE2: |==id0==|        |==id1==|        |==id0==|        |==id1==|
V:          |==id0==|        |==id1==|        |==id0==|        |==id1==|
MTE3:            |==id0==|        |==id1==|        |==id0==|        |==id1==|
</code></pre></div></article></div>`,1)])])}const h=a(l,[["render",_]]);export{u as __pageData,h as default};
